// Input here is Claude's answer. The lead itself came from the earlier node,
// so we fetch it back by name and glue the two together.

const src  = $input.item.json;
const lead = $('Clean & validate').item.json;

// The LLM chain usually returns its answer in `text`.
const raw = (src.text ?? src.output ?? src.response ?? '').toString();

// Models sometimes wrap JSON in prose or in ``` fences. Dig the object out.
function extractJson(str) {
  const fenced = str.match(/```(?:json)?\s*([\s\S]*?)```/);
  const body   = fenced ? fenced[1] : str;
  const start  = body.indexOf('{');
  const end    = body.lastIndexOf('}');
  if (start === -1 || end === -1) return null;
  try { return JSON.parse(body.slice(start, end + 1)); } catch (e) { return null; }
}

const ai = extractJson(raw);

// If the model misbehaved, keep the lead and flag it rather than losing it.
// A dropped enquiry is a lost customer; a flagged one is a two-minute job.
if (!ai) {
  return {
    json: {
      ...lead,
      service: '',
      urgency: '',
      summary: '',
      status: 'needs_review',
      ai_error: 'Could not parse model output',
      ai_raw: raw.slice(0, 300),
    },
  };
}

// Never trust a model to stay inside its options - check every field
// that has a fixed set of answers, not just the one you thought about first.
const URGENCIES = ['urgent', 'normal', 'low'];
const SERVICES  = ['repair', 'installation', 'quote_request', 'billing', 'general'];

const urgency = URGENCIES.includes(ai.urgency) ? ai.urgency : 'normal';
const service = SERVICES.includes(ai.service)  ? ai.service  : 'general';

return {
  json: {
    ...lead,
    service,
    urgency,
    summary: ai.summary ?? '',
    // A lead flagged in the earlier step stays flagged.
    status: lead.status === 'needs_review' ? 'needs_review' : 'new',
    ai_error: '',
  },
};

