// Paste this whole block. You should NOT need to edit anything.
// It finds each answer by matching part of the field name, so it works
// no matter what you called the fields on your form.

const src  = $input.item.json;
const keys = Object.keys(src);
const used = new Set();

// Find the first unused key whose name contains one of these words.
function pick(...needles) {
  for (const needle of needles) {
    const hit = keys.find(k =>
      !used.has(k) &&
      k.toLowerCase().replace(/[^a-z]/g, '').includes(needle)
    );
    if (hit) { used.add(hit); return src[hit]; }
  }
  return '';
}

// Collapse whitespace and trim. Handles null/undefined without throwing.
const text = (v) => (v ?? '').toString().trim().replace(/\s+/g, ' ');

// Most specific first, so each one claims its own field.
const email   = text(pick('email', 'mail')).toLowerCase();
let   phone   = text(pick('phone', 'tel', 'mobile', 'cell'));
const name    = text(pick('name'));
const message = text(pick('help', 'message', 'need', 'comment', 'detail', 'describe'));

// Strip everything that isn't a digit, then drop a leading US country code.
phone = phone.replace(/\D/g, '');
if (phone.length === 11 && phone.startsWith('1')) phone = phone.slice(1);

// Flag problems instead of writing a broken row and hoping.
const missing = [];
if (!name) missing.push('name');
if (!email.includes('@') || !email.includes('.')) missing.push('email');
if (phone.length !== 10) missing.push('phone');
if (message.length < 3) missing.push('message');

return {
  json: {
    timestamp: src.submittedAt ?? new Date().toISOString(),
    name,
    email,
    phone,
    message,
    status: missing.length ? 'needs_review' : 'new',
    missing: missing.join(', '),      // not written to the sheet - for you to read
  },
};
